import {clamp,colorCSS} from './math.js';
import {NerfFitter,NERF_BG,NERF_VIEWS,NERF_RESERVED,RAY_PIXELS,makeRay,marchRay,referenceRadiance} from './nerf-math.js';

const control=(id,label,min,max,step,value)=>`<label class="control"><span>${label}<output id="${id}-out"></output></span><input id="${id}" aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
export class NerfLab{
  constructor(){this.fitter=new NerfFitter();this.resetState();}
  resetState(){this.yaw=90;this.pixel=16;this.samples=32;this.training=[0,1,2];this.source='reference';this.running=false;this.element=null;this.message='Inspect a ray through the reference field, then train the coordinate MLP from pixel colours.';}
  unmount(){this.running=false;cancelAnimationFrame(this.animation);this.element=null;}
  reset(){this.unmount();this.fitter.reset();this.resetState();}
  q(s){return this.element.querySelector(s);}
  mount(element,next,back){this.element=element;
    element.innerHTML=`<div class="module-heading"><div><p class="eyebrow">06 / NeRF · NEURAL RADIANCE FIELDS</p><h2>Fit a field, then integrate camera rays.</h2><p class="description">Gaussian Splatting stores explicit primitives. A NeRF stores a scene in network weights: query a position for density and a position plus viewing direction for colour. Both can learn by comparing rendered pixels.</p></div><aside class="model-note"><strong>A trainable cross-section</strong>This browser model has two spatial inputs (x,z), two 24-unit layers, and a direction-dependent RGB head. Full NeRF uses 3D positions. Its reference field is visible for explanation; only camera-ray RGB targets supervise training.</aside></div>
    <div class="nerf-pipeline" aria-label="Neural field rendering and fitting pipeline"><span>Ray positions (x,z)<small>Fourier features γ</small></span><b>→</b><span>Shared MLP<small>learned weights θ</small></span><b>→</b><span>Density σ ≥ 0<small>RGB also uses direction d</small></span><b>→</b><span>Volume integration<small>α = 1−exp(−σδ)</small></span><b>→</b><span>Pixel colour<small>compare → backpropagate</small></span></div>
    <div class="lab-layout"><aside class="controls"><div class="panel-heading"><h3>Ray + neural field</h3><button id="nerf-reset" class="text-button">Reset ↺</button></div>${control('nerf-yaw','Inspection camera yaw',-180,180,1,this.yaw)}${control('nerf-pixel','Sampled pixel / ray',0,32,1,this.pixel)}<label class="control"><span>Samples per ray</span><select id="nerf-samples">${[8,16,32,64].map(n=>`<option ${n===this.samples?'selected':''}>${n}</option>`).join('')}</select></label><label class="control"><span>Inspect ray through</span><select id="nerf-source"><option value="reference">Reference field</option><option value="learned">Learned MLP field</option></select></label><label class="control"><span>Training observations</span><select id="nerf-training"><option value="three">Three separated camera rows</option><option value="one">One camera row</option></select></label><p class="control-note">Camera rows contain 33 RGB pixels. Changing the training set resets the same network initialization. Camera 0° is always reserved. Sampling changes quadrature, not network size.</p><div class="button-row"><button id="nerf-run" class="primary-button">Run neural fit ▷</button><button id="nerf-step" class="small-button">1 update</button><button id="nerf-step50" class="small-button">Fit 50 updates</button><button id="nerf-restart" class="text-button">Restart weights ↺</button></div><p class="control-note">Adam updates the actual MLP through the ray renderer. A batch contains 12 training rays. No target density or pointwise colour labels are given to the network.</p></aside>
    <div class="visual"><div class="visual-toolbar"><span>2D SPATIAL CROSS-SECTION / x HORIZONTAL · z VERTICAL</span><span>Rays are inspected through both fields</span></div><div class="nerf-fields"><section><h3>REFERENCE · ANALYTIC PRIMITIVE FIELD</h3><canvas id="nerf-reference" width="360" height="360" aria-label="Reference density and colour in a two-dimensional scene cross-section, with selected camera ray and samples."></canvas></section><section><h3>LEARNED · COORDINATE MLP</h3><canvas id="nerf-learned" width="360" height="360" aria-label="Learned neural density and colour field with the same camera ray."></canvas></section></div><p class="nerf-caption">Field display mixes RGB toward white by 1−exp(−0.2σ) to reveal density; this is an inspection slice with RGB queried at the selected ray direction. Dots mark the actual ray samples. Large dots contribute more to the selected pixel.</p><div class="nerf-rows"><div><b>REFERENCE CAMERA ROW</b><canvas id="nerf-target-row" width="660" height="38" tabindex="0" aria-label="Reference camera row of 33 pixels; click or use arrows to select a ray."></canvas></div><div><b>MLP CAMERA ROW</b><canvas id="nerf-prediction-row" width="660" height="38" tabindex="0" aria-label="Predicted camera row of 33 pixels; click or use arrows to select a ray."></canvas></div></div><div class="nerf-camera-buttons"><span>Inspect a known pose:</span>${NERF_VIEWS.map((yaw,i)=>`<button class="small-button" data-nerf-view="${i}">${yaw}° · ${i===NERF_RESERVED?'reserved':'capture'}</button>`).join('')}</div><div class="metrics"><div class="metric"><span>Training pixel MSE</span><strong id="nerf-train-loss"></strong><small id="nerf-train-label"></small></div><div class="metric"><span>Reserved 0° MSE</span><strong id="nerf-test-loss"></strong><small>Excluded from all gradients</small></div><div class="metric"><span>Weights / updates</span><strong id="nerf-count"></strong><small>Continuous queries, fixed parameter count</small></div></div></div></div>
    <p class="story-log" id="nerf-status" role="status"></p><div class="visual nerf-ray-visual"><div class="visual-toolbar"><span id="nerf-ray-heading"></span><span>FRONT → BACK ALONG THE SELECTED RAY</span></div><canvas id="nerf-ray-chart" width="960" height="220" aria-label="Density and termination weights along the selected ray, shown as separate bar charts."></canvas><div class="nerf-ray-result"><span id="nerf-rgb"></span><span id="nerf-trans"></span></div><div class="table-wrap nerf-sample-table" tabindex="0" aria-label="Scrollable ray-sample table"><table><thead><tr><th>Sample</th><th>Distance t</th><th>Density σ</th><th>Interval δ</th><th>Alpha</th><th>T before</th><th>Weight Tα</th></tr></thead><tbody id="nerf-sample-rows"></tbody></table></div></div>
    <div class="formula-row"><div><span>A neural radiance field</span><code>σ = σθ(x); c = cθ(x,d)</code></div><div><span>Density becomes segment opacity</span><code>αᵢ = 1−exp(−σᵢδᵢ)</code></div><div><span>The familiar blending recurrence</span><code>C = Σᵢ Tᵢαᵢcᵢ + T_end c_bg</code></div></div><p class="experiment-note"><b>TRY THIS</b>At 90°, inspect the centre ray: the near cyan region can hide orange density behind it. Compare σ with Tα. Switch between 8 and 64 samples, then fit the neural field and inspect the reserved camera. Does low training error establish the correct density everywhere?</p>
    <section class="nerf-comparison"><p class="eyebrow">SAME SUPERVISION · DIFFERENT SCENE PARAMETERIZATION</p><h3>Where do NeRF and Gaussian Splatting differ?</h3><div class="table-wrap"><table><thead><tr><th>Question</th><th>3D Gaussian Splatting</th><th>Original NeRF family</th></tr></thead><tbody><tr><td>What stores the scene?</td><td>Explicit Gaussian means, covariances, opacity, appearance</td><td>Weights of a coordinate network returning density and radiance</td></tr><tr><td>How is a pixel formed?</td><td>Project splats and blend their screen footprints</td><td>Query samples along a camera ray and integrate their contributions</td></tr><tr><td>What is learned?</td><td>Primitive parameters; density control can add or remove primitives</td><td>Network weights; ray sampling selects where the field is evaluated</td></tr><tr><td>How can colour depend on view?</td><td>Appearance coefficients such as spherical harmonics</td><td>A colour branch conditioned on viewing direction</td></tr><tr><td>What does an RGB image constrain?</td><td colspan="2">Rendered rays; neither representation automatically guarantees correct surfaces in unobserved regions</td></tr></tbody></table></div></section>
    <details class="concept-details"><summary>What is simplified, and what is actually being optimized?</summary><p>This is a real coordinate MLP optimized from rendered pixel targets, with analytic backpropagation through both the network and transmittance. The reference is a bounded 2D field containing a rectangle, a circle, and a thin bar. RGB depends mildly on ray direction; density depends only on position. The stored observations are four camera rows, each integrated at 256 samples. Only selected training rows supply gradients.</p><p>Position inputs include two sine/cosine frequency bands, which are fixed features rather than extra scene observations. The toy uses tanh hidden units, softplus density, sigmoid RGB, and uniform midpoint quadrature. It does not reproduce the full NeRF architecture, random stratified training samples, hierarchical coarse/fine sampling, or full 3D image training. Changing sample count keeps weights fixed; it changes the numerical forward model used for display and subsequent fitting. All comparisons here are teaching experiments, not a speed or quality benchmark between methods.</p><p>More ray samples improve integration of the current field when they resolve its variation. They do not add training cameras, remove depth ambiguity, or increase network capacity. Adaptive sampling and Gaussian density control act on different things: evaluation locations versus scene parameters.</p><a href="https://arxiv.org/html/2003.08934v2#S3" target="_blank" rel="noreferrer">Mildenhall et al. · NeRF (ECCV 2020), §§3–5 ↗</a></details><div class="bottom-nav"><button id="nerf-back" class="text-button">← Revisit Gaussian reconstruction</button><button id="nerf-next" class="text-button">Next: Real Garden rendered with Gaussian Splatting →</button></div>`;
    this.q('#nerf-reset').onclick=()=>{this.reset();this.mount(element,next,back);};this.q('#nerf-next').onclick=next;this.q('#nerf-back').onclick=back;
    this.q('#nerf-yaw').oninput=e=>{this.yaw=Number(e.target.value);this.update();};this.q('#nerf-pixel').oninput=e=>{this.pixel=Number(e.target.value);this.update();};this.q('#nerf-source').onchange=e=>{this.source=e.target.value;this.update();};this.q('#nerf-samples').onchange=e=>{this.stop();this.samples=Number(e.target.value);this.message='Same network weights. Changed ray quadrature for display, evaluation, and subsequent fitting.';this.update();};this.q('#nerf-training').onchange=e=>{this.training=e.target.value==='one'?[0]:[0,1,2];this.restart();};this.q('#nerf-restart').onclick=()=>this.restart();
    this.q('#nerf-step').onclick=()=>this.steps(1);this.q('#nerf-step50').onclick=()=>this.steps(50);this.q('#nerf-run').onclick=()=>{cancelAnimationFrame(this.animation);this.running=!this.running;if(this.running)this.tick();this.update();};
    element.querySelectorAll('[data-nerf-view]').forEach(b=>b.onclick=()=>{this.yaw=NERF_VIEWS[Number(b.dataset.nerfView)];this.update();});
    for(const id of ['nerf-target-row','nerf-prediction-row']){const canvas=this.q('#'+id);canvas.onclick=e=>{const b=canvas.getBoundingClientRect();this.pixel=clamp(Math.floor((e.clientX-b.x)/b.width*33),0,32);this.update();};canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();this.pixel=clamp(this.pixel+(e.key==='ArrowRight'?1:-1),0,32);this.update();};}
    this.update();
  }
  stop(){this.running=false;cancelAnimationFrame(this.animation);}
  restart(){this.stop();this.fitter.reset();this.message='Restarted the same network weights. Only the selected camera rows supervise the fit.';this.update();}
  steps(n){for(let i=0;i<n&&this.fitter.iteration<1200;i++)this.fitter.step(this.training,this.samples);this.source='learned';if(this.fitter.iteration>=1200)this.stop();this.message='Updated network weights through rendered training rays. The reserved 0° camera supplied no gradients.';this.update();}
  tick(){if(!this.running||!this.element)return;this.steps(5);if(this.running)this.animation=requestAnimationFrame(()=>this.tick());}
  update(){if(!this.element)return;
    this.q('#nerf-yaw').value=this.yaw;this.q('#nerf-yaw-out').textContent=this.yaw+'°';this.q('#nerf-pixel').value=this.pixel;this.q('#nerf-pixel-out').textContent=this.pixel+' / 32';this.q('#nerf-source').value=this.source;this.q('#nerf-samples').value=this.samples;this.q('#nerf-training').value=this.training.length===1?'one':'three';this.q('#nerf-status').textContent=this.message;this.q('#nerf-run').textContent=this.running?'Pause neural fit':'Run neural fit ▷';for(const id of ['nerf-run','nerf-step','nerf-step50'])this.q('#'+id).disabled=this.fitter.iteration>=1200;
    const learned=(p,d)=>this.fitter.model.query(p,d),ray=makeRay(this.yaw,this.pixel),reference=marchRay(referenceRadiance,ray,this.samples),prediction=marchRay(learned,ray,this.samples),selected=this.source==='reference'?reference:prediction;
    this.drawField('nerf-reference',referenceRadiance,reference,ray);this.drawField('nerf-learned',learned,prediction,ray);
    this.drawRow('nerf-target-row',referenceRadiance);this.drawRow('nerf-prediction-row',learned);
    this.q('#nerf-train-loss').textContent=this.fitter.evaluate(this.training,this.samples).toFixed(5);this.q('#nerf-test-loss').textContent=this.fitter.evaluate([NERF_RESERVED],this.samples).toFixed(5);this.q('#nerf-train-label').textContent=this.training.length+' camera rows · selected pixels only';this.q('#nerf-count').textContent=this.fitter.model.weights.length+' / '+this.fitter.iteration;
    this.q('#nerf-ray-heading').textContent=`${this.source==='reference'?'REFERENCE':'LEARNED'} FIELD · PIXEL ${this.pixel} · YAW ${this.yaw}°`;
    this.q('#nerf-sample-rows').innerHTML=selected.rows.map((r,i)=>`<tr><td>${i+1}</td><td>${r.distance.toFixed(3)}</td><td>${r.sigma.toFixed(3)}</td><td>${r.delta.toFixed(3)}</td><td>${r.alpha.toFixed(4)}</td><td>${r.t.toFixed(4)}</td><td>${r.weight.toFixed(4)}</td></tr>`).join('')||'<tr><td colspan="7">Ray misses the bounded field; only background contributes.</td></tr>';
    this.q('#nerf-rgb').textContent='Pixel RGB = ('+selected.color.map(v=>v.toFixed(3)).join(', ')+')';this.q('#nerf-trans').textContent='T_end = '+selected.t.toFixed(5);this.drawRay(selected);
  }
  drawField(id,field,render,ray){const canvas=this.q('#'+id),ctx=canvas.getContext('2d'),small=document.createElement('canvas');small.width=small.height=80;const sc=small.getContext('2d'),img=sc.createImageData(80,80);
    for(let y=0;y<80;y++)for(let x=0;x<80;x++){const q=field([-1+2*x/79,1-2*y/79],ray.direction),a=-Math.expm1(-.2*q.sigma),off=4*(y*80+x);for(let c=0;c<3;c++)img.data[off+c]=255*(1-a+a*q.color[c]);img.data[off+3]=255;}
    sc.putImageData(img,0,0);ctx.imageSmoothingEnabled=true;ctx.drawImage(small,0,0,360,360);const screen=p=>[(p[0]+1)*180,(1-p[1])*180];
    if(render.rows.length){const first=screen(ray.origin.map((v,i)=>v+ray.near*ray.direction[i])),last=screen(ray.origin.map((v,i)=>v+ray.far*ray.direction[i]));ctx.strokeStyle='#234e69';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(...first);ctx.lineTo(...last);ctx.stroke();for(const r of render.rows){const p=screen(r.p);ctx.fillStyle=r.weight>.02?'#a16c2c':'#446e8790';ctx.beginPath();ctx.arc(p[0],p[1],1.2+5*Math.sqrt(r.weight),0,Math.PI*2);ctx.fill();}const a=screen(ray.origin.map((v,i)=>v+(ray.near+.12)*ray.direction[i])),b=screen(ray.origin.map((v,i)=>v+(ray.near+.23)*ray.direction[i])),angle=Math.atan2(b[1]-a[1],b[0]-a[0]);ctx.beginPath();ctx.moveTo(b[0]-9*Math.cos(angle-.5),b[1]-9*Math.sin(angle-.5));ctx.lineTo(...b);ctx.lineTo(b[0]-9*Math.cos(angle+.5),b[1]-9*Math.sin(angle+.5));ctx.stroke();}
    ctx.fillStyle='#56768d';ctx.font='11px monospace';ctx.fillText('x,z ∈ [−1,1] · ray entry → exit',10,348);
  }
  drawRow(id,field){const ctx=this.q('#'+id).getContext('2d');for(let i=0;i<RAY_PIXELS;i++){const color=marchRay(field,makeRay(this.yaw,i),this.samples).color;ctx.fillStyle=colorCSS(color);ctx.fillRect(i*20,0,20,38);}ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.strokeRect(this.pixel*20+2,2,16,34);ctx.strokeStyle='#244e65';ctx.lineWidth=1.5;ctx.strokeRect(this.pixel*20+2,2,16,34);}
  drawRay(render){const ctx=this.q('#nerf-ray-chart').getContext('2d');ctx.fillStyle='#f7fbfe';ctx.fillRect(0,0,960,220);const rows=render.rows,width=860/Math.max(1,rows.length),densityMax=Math.max(1,...rows.map(r=>r.sigma)),weightMax=Math.max(.01,...rows.map(r=>r.weight));
    for(const [key,top,height,max,color]of [['sigma',25,64,densityMax,'#2a92b8'],['weight',125,64,weightMax,'#b6813f']]){ctx.fillStyle='#55738a';ctx.font='12px monospace';ctx.fillText(key==='sigma'?`DENSITY σ · max ${max.toFixed(2)}`:`WEIGHT Tα · max ${max.toFixed(3)}`,24,top-7);rows.forEach((r,i)=>{const h=r[key]/max*height;ctx.fillStyle=color;ctx.fillRect(70+i*width,top+height-h,Math.max(1,width-2),h);});ctx.strokeStyle='#cadfea';ctx.beginPath();ctx.moveTo(70,top+height);ctx.lineTo(930,top+height);ctx.stroke();}ctx.fillStyle='#607e93';ctx.fillText('Front / ray entry',70,213);ctx.textAlign='right';ctx.fillText('Back / ray exit',930,213);ctx.textAlign='left';
  }
}
